    ('PP-ASEL-0094', 'Private, Flight Instructor', 'ASEL', 'PA.V.B; FI.IX.E', 'What is the difference between S-Turns over a road (or other straight object on the ground) and Turns-Around a Point?', 'Remember keep the same radius on turns-around-a point. Announce when you are steep and when you shallow in your turns around a point. S-turns require different excursion distances from the road depending on wind.', 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'V. Performance Maneuvers and Ground Reference Maneuvers; IX. Performance and Ground Reference Maneuvers', 'PA.V.B Ground Reference Maneuvers; FI.IX.E Ground Reference Maneuvers', 'knowledge', 'standard'),
    ('PP-ASEL-0095', 'Private, Flight Instructor', 'ASEL', 'PA.V.B; FI.IX.E', 'Why are “Clearing Turns” required before each maneuver?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'V. Performance Maneuvers and Ground Reference Maneuvers; IX. Performance and Ground Reference Maneuvers', 'PA.V.B Ground Reference Maneuvers; FI.IX.E Ground Reference Maneuvers', 'knowledge', 'standard'),
    ('PP-ASEL-0096', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.VII.C; CA.VII.C; FI.X.D', 'Why do you need your right foot handy when doing a power on stall to a break?', null, 'FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; POH/AFM', 'VII. Slow Flight and Stalls; X. Slow Flight, Stalls, and Spins', 'PA.VII.C Power-On Stalls; CA.VII.C Power-On Stalls; FI.X.D Power-On Stalls', 'knowledge', 'standard'),
    ('PP-ASEL-0097', 'Private, Flight Instructor', 'ASEL', 'PA.VIII.B; FI.XI.B', 'What is a constant rate climb? What is a constant rate turn-bank? How many degrees of turn is the aircraft in when performing a constant rate turn-bank?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'VIII. Basic Instrument Maneuvers; XI. Basic Instrument Maneuvers', 'PA.VIII.B Constant Airspeed Climbs; FI.XI.B Constant Airspeed Climbs', 'knowledge', 'standard'),
    ('PP-ASEL-0098', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.IV.A/B; CA.IV.A/B; FI.VII.A/B', 'What is a stabilized descent? List several elements.', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'IV. Takeoffs, Landings, and Go-Arounds; VII. Takeoffs, Landings, and Go-Arounds', 'PA.IV.A/B Normal Takeoff and Climb / Normal Approach and Landing; CA.IV.A/B Normal Takeoff and Climb / Normal Approach and Landing; FI.VII.A/B Normal Takeoff and Climb / Normal Approach and Landing', 'knowledge', 'standard'),
    ('PP-ASEL-0099', 'Private, Flight Instructor', 'ASEL', 'PA.VIII.E; FI.XI.E', 'Describe “UNUSUAL ATITUDES”. What can you as a pilot do to get out of one of those? Procedures.', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'VIII. Basic Instrument Maneuvers; XI. Basic Instrument Maneuvers', 'PA.VIII.E Recovery from Unusual Flight Attitudes; FI.XI.E Recovery from Unusual Flight Attitudes', 'knowledge', 'standard'),
    ('PP-ASEL-0100', 'Private, Flight Instructor', 'ASEL', 'PA.IV.M; FI.VII.M', 'Describe how to do a “FORWARD SLIP”. Why would you ever want to do one of those?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'IV. Takeoffs, Landings, and Go-Arounds; VII. Takeoffs, Landings, and Go-Arounds', 'PA.IV.M Forward Slip to a Landing; FI.VII.M Slip to a Landing', 'knowledge', 'standard'),
    ('PP-ASEL-0101', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.VII.C; CA.VII.C; FI.X.D', 'Why do we slow the aircraft to below 80 MPH prior to doing a “POWER-ON STALL?', null, 'FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; POH/AFM', 'VII. Slow Flight and Stalls; X. Slow Flight, Stalls, and Spins', 'PA.VII.C Power-On Stalls; CA.VII.C Power-On Stalls; FI.X.D Power-On Stalls', 'knowledge', 'standard'),
    ('PP-ASEL-0102', 'Private, Flight Instructor', 'ASEL', 'PA.V.B; FI.IX.E', 'What is “TURNS AROUND A POINT” and how do you do them according to the ACS? What are safety concerns and plans to alleviate?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'V. Performance Maneuvers and Ground Reference Maneuvers; IX. Performance and Ground Reference Maneuvers', 'PA.V.B Ground Reference Maneuvers; FI.IX.E Ground Reference Maneuvers', 'knowledge', 'standard'),
    ('PP-ASEL-0103', 'Private, Flight Instructor', 'ASEL', 'PA.V.B; FI.IX.E', 'What are “S-TURNS ACROSS A ROAD (or something straight)? How do you do them? What are safety concerns?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'V. Performance Maneuvers and Ground Reference Maneuvers; IX. Performance and Ground Reference Maneuvers', 'PA.V.B Ground Reference Maneuvers; FI.IX.E Ground Reference Maneuvers', 'knowledge', 'standard'),
    ('PP-ASEL-0104', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.VII; CA.VII; FI.X', 'According to the ACS… What is the minimum altitude you should keep when doing altitude changing maneuvers such as STALLS? What are safety concerns? Define a “clearing turn”.', null, 'FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; POH/AFM', 'VII. Slow Flight and Stalls; X. Slow Flight, Stalls, and Spins', 'PA.VII Slow Flight / Stalls; CA.VII Slow Flight / Stalls; FI.X Slow Flight / Stalls / Spins', 'knowledge', 'standard'),
    ('PP-ASEL-0105', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.IV.A/B; CA.IV.A/B; FI.VII.A/B', 'What is meant by “Controlled Descent”?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'IV. Takeoffs, Landings, and Go-Arounds; VII. Takeoffs, Landings, and Go-Arounds', 'PA.IV.A/B Normal Takeoff and Climb / Normal Approach and Landing; CA.IV.A/B Normal Takeoff and Climb / Normal Approach and Landing; FI.VII.A/B Normal Takeoff and Climb / Normal Approach and Landing', 'knowledge', 'standard'),
    ('PP-ASEL-0106', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.VI.C; CA.VI.C; FI.II.I', 'What is meant by “A DIVERSION” as referenced by the ACS? What is expected of you?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; VFR Navigation Charts', 'VI. Navigation; II. Technical Subject Areas', 'PA.VI.C Diversion; CA.VI.C Diversion; FI.II.I Navigation and Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('PP-ASEL-0107', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.IX.C; CA.IX.C; FI.XII.C', 'WE are flying along and the aircraft battery seems to be discharging (ammeter goes to the left). What do we do?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; POH/AFM', 'IX. Emergency Operations; XII. Emergency Operations', 'PA.IX.C Systems and Equipment Malfunctions; CA.IX.C Systems and Equipment Malfunctions; FI.XII.C Systems and Equipment Malfunctions', 'scenario', 'standard'),
    ('PP-ASEL-0108', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.IX.C; CA.IX.C; FI.XII.C', 'Both gas tanks show empty gauges. What do we do?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; POH/AFM', 'IX. Emergency Operations; XII. Emergency Operations', 'PA.IX.C Systems and Equipment Malfunctions; CA.IX.C Systems and Equipment Malfunctions; FI.XII.C Systems and Equipment Malfunctions', 'scenario', 'standard'),
    ('PP-ASEL-0109', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.C; CA.I.C; FI.III.C', 'WE are deciding whether to make a trip or not. There are lots of thunderstorms in the area but it looks like our flight might work. What should you do? What would be the best weather charts to consult?', null, '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28', 'I. Preflight Preparation; III. Preflight Preparation', 'PA.I.C Weather Information; CA.I.C Weather Information; FI.III.C Weather Information', 'scenario', 'standard'),
    ('PP-ASEL-0110', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.IX.C; CA.IX.C; FI.XII.C', 'WE taxi out to take-off and find that one magnito is running rough. What now?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; POH/AFM', 'IX. Emergency Operations; XII. Emergency Operations', 'PA.IX.C Systems and Equipment Malfunctions; CA.IX.C Systems and Equipment Malfunctions; FI.XII.C Systems and Equipment Malfunctions', 'scenario', 'standard'),
    ('PP-ASEL-0111', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.B; CA.I.B; FI.III.B', 'WE smell smoke in the cabin and suspect a fire could be imminent. What do we do?', null, '14 CFR parts 39, 43, 91; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25', 'I. Preflight Preparation; III. Preflight Preparation', 'PA.I.B Airworthiness Requirements; CA.I.B Airworthiness Requirements; FI.III.B Airworthiness Requirements', 'scenario', 'standard'),
    ('PP-ASEL-0112', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.H; CA.I.H; FI.II.A', 'WE have a passenger that is feeling very hot and reports not feeling so well. What do you do?', null, 'AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25', 'I. Preflight Preparation; II. Technical Subject Areas', 'PA.I.H Human Factors; CA.I.H Human Factors; FI.II.A Human Factors', 'scenario', 'standard'),
    ('PP-ASEL-0113', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.A; CA.I.A; FI.II.J', 'You have a parachutist friend who wants to jump out of your aircraft. Can you allow that?', null, '14 CFR parts 61 and 91; AIM; FAA-H-8083-25', 'I. Preflight Preparation; II. Technical Subject Areas', 'PA.I.A Pilot Qualifications / Regulatory Responsibilities; CA.I.A Pilot Qualifications / Regulatory Responsibilities; FI.II.J 14 CFR and Publications', 'scenario', 'standard'),
    ('PP-ASEL-0114', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.A; CA.I.A; FI.II.J', 'You have another friend (strange friends..but I digress) that wants to drop human ashes out of your plane. Can you allow that? Considerations?', null, '14 CFR parts 61 and 91; AIM; FAA-H-8083-25', 'I. Preflight Preparation; II. Technical Subject Areas', 'PA.I.A Pilot Qualifications / Regulatory Responsibilities; CA.I.A Pilot Qualifications / Regulatory Responsibilities; FI.II.J 14 CFR and Publications', 'scenario', 'standard'),
    ('PP-ASEL-0115', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.A; CA.I.A; FI.III.A', 'What do you do if you have not flown for over a year and you want to get your privileges back to carry passengers?', null, '14 CFR parts 61, 68, 91; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25', 'I. Preflight Preparation; III. Preflight Preparation', 'PA.I.A Pilot Qualifications; CA.I.A Pilot Qualifications; FI.III.A Pilot Qualifications', 'scenario', 'standard'),
    ('PP-ASEL-0116', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.A; CA.I.A; FI.II.J', 'The FAA tower controller calls you up and asks you to call the tower when you land for a possible violation. He gives you the phone number. What do you do and what are your concerns?', null, '14 CFR parts 61 and 91; AIM; FAA-H-8083-25', 'I. Preflight Preparation; II. Technical Subject Areas', 'PA.I.A Pilot Qualifications / Regulatory Responsibilities; CA.I.A Pilot Qualifications / Regulatory Responsibilities; FI.II.J 14 CFR and Publications', 'scenario', 'standard'),
    ('PP-ASEL-0117', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.A; CA.I.A; FI.III.A', 'A friend offers to pay you to take him or a parcel of some kind to a location several miles away. What are your considerations?', null, '14 CFR parts 61, 68, 91; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25', 'I. Preflight Preparation; III. Preflight Preparation', 'PA.I.A Pilot Qualifications; CA.I.A Pilot Qualifications; FI.III.A Pilot Qualifications', 'scenario', 'standard'),
    ('PP-ASEL-0118', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.A; CA.I.A; FI.III.A', 'What is the "standard" to determine if you can "share" costs with your passenger?', null, '14 CFR parts 61, 68, 91; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25', 'I. Preflight Preparation; III. Preflight Preparation', 'PA.I.A Pilot Qualifications; CA.I.A Pilot Qualifications; FI.III.A Pilot Qualifications', 'scenario', 'standard'),
    ('PP-ASEL-0119', 'Private, Commercial, Flight Instructor', 'ASEL', 'PA.I.G; CA.I.G; FI.II.E', 'You are starting your engine on a cold day and may have given the engine too many “prime” pumps. Fuel is dripping from the engine. When you crank the engine it suddenly backfires and someone yells “your engine is on fire!!” What do you do?', null, 'FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-23; FAA-H-8083-25; POH/AFM', 'I. Preflight Preparation; II. Technical Subject Areas', 'PA.I.G Operation of Systems; CA.I.G Operation of Systems; FI.II.E Aircraft Flight Controls and Operation of Systems', 'scenario', 'standard'),
    ('IR-ASEL-0001', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'When do you need an IFR rating?', '• Flying by instrument flight rules (IFR flight plan) • Weather less than minimums for VFR • Class A airspace • Under special VFR within Class B, C, D, & E surfaces areas between sunset and sunrise • Flying for hire with passengers on cross country flights greater than 50NM or at night', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0002', 'Instrument', 'Instrument Airplane', 'IR.I.C', '* Added from Exam Guide. What information must the PIC be aware of before flight?', '• NOTAMS • Weather reports & forecasts • Known ATC traffic delays • Runway lengths of airport at intended use • Alternatives available if planned flight cannot be completed • Fuel Available', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0003', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'Explain Currency', 'Currency is valid for the 6 months following check ride or proficiency check. Within those 6 months, Pilot must have logged 6 instrumented approaches including intercepting/tracking courses using navigation systems, and holding procedures.', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0004', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'What happens when currency expires?', 'If beyond the 6 months, you must go and conduct the 6 instrument approaches with intercepting/tracking course, and holding procedures in an FAA approved sim / training device with a CFII, in an aircraft under the hood with safety pilot of CFII. Finish the remaining activities in a sim or airplane with safety pilot', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0005', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'What happens if you exceed 12 months?', '• Instrument proficiency check- check ride sequence with DE or CFII', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0006', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'What documents must pilots carry?', '• Pilot License with Instrument Rating • Valid Medical • Photo ID', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0007', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'How to log instrument time?', '• Location, name of approach, and name of safety pilot (if applicable)', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0008', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.II.C', 'What documents must be aboard for IFR?', '• The airplane must be certified for IFR • GPS Airworthiness Certificate and Instruction manual (supplemental AFM) • Current GPS chip and logged • VOR check and logged within 30 days of flight • VFR (ARROW)JILI • Instrument GRABCARD (VFR day and night) & AAV1ATE (tests and inspections for IFR)- page 1-12 oral exam guide- pull up', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'II. Preflight Procedures', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.II.C Instrument Flight Deck Check', 'knowledge', 'standard'),
    ('IR-ASEL-0009', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'When do you have to file an IFR flight plan and receive an IFR clearance?', '• Whenever you are flying IMC in controlled airspace', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0010', 'Instrument', 'Instrument Airplane', 'IR.III.A', 'What is a “void if not of by” clearance?', '2 • A clearance provided by ATC at non- towered airports to permit take off IFR from the airport. Failure to become airborne by this time results in an automatically void IFR clearance. The pilot is to request for a new IFR clearance. The pilot has 30 mins from the clearance void time to notify ATC of their intentions if not airborne else search and rescue will initiate. • Clearance void if not off by 14:00. Can’t take off after 14:00. You have 30 mins from then to call and tell them not off the ground. Unless they tell you call us back 14:20. Means you have only 20 mins to call back and say didn’t take off.', '14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16', 'III. Air Traffic Control (ATC) Clearances and Procedures', 'IR.III.A Compliance with Air Traffic Control Clearances', 'knowledge', 'standard'),
    ('IR-ASEL-0011', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'When do I have to file an alternate? (1-2-3 rule)', 'When you have less than 3 SM visibility or less than 2000ft ceiling 1 hour before or 1 hour after the ETA, then an alternate airport is required', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0012', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'What are the standard alternate airport minimum requirements to use published approach procedures?', '• Precision Approach: 600ft/2SM vis • Non-Precision Approach: 800ft/2SM vis • To follow these standard requirements unless specific airport minima specified in the approach plate', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0013', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'Can I assign a VFR airport (no Instrument Approach Procedures) as an alternate?', '• Yes, if you are able to leave the enroute structure and descend to the airport in VMC.', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0014', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'What are the fuel requirements for an IFR flight?', '• To Final Destination: Fuel to your final destination plus 45 minutes reserve at normal cruising speed • If Alternate airport is required: Fuel to your final destination plus to your alternate plus 45 minutes reserve at normal cruising speed', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0015', 'Instrument', 'Instrument Airplane', 'IR.II.A', 'Can you as PIC of an IFR flight allow portable electronic devices to be used by passengers?', '• During critical phases of flight (Take-off and landing) please request passengers to stow portable electronic devices that transmit or receive RF signals.', '14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'II. Preflight Procedures', 'IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0016', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'What are the takeoff minimums for IFR flight?', '• Part 91: Unrestricted – This is our category • Part 135 & 121 : Use Obstacle departure procedure and interpret standard minimums i. Dependent on number of engines 1. 1-2 Engines require 1 SM vis 2. 3+ Engines require ½ SM vis 3. Airline Ops Specs generally ¼ Mile', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0017', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'After filing an IFR flight plan, can you take off VFR, fly controlled airspace and radio for your IFR clearance?', '• Yes, you can request it in the air but you should do so and receive it before entering IMC. As long as you stay VFR.', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0018', 'Instrument', 'Instrument Airplane', 'IR.V.B', 'Define the following terms', '• MEA- Minimum En-route Altitude- provides reception for NavAids and obstacle clearance • MOCA- Minimum Obstacle Clearance Altitude- provides clearance from obstacles/terrain plus 2000’ mountainous and 1000’ non-mountainous regions 3 • MORCA- Minimum Off-Route Clearance Altitude- provides obstacle clearance when travelling off pre-set routes (i.e. victor airways). Large letters in brown in IFR sectional That 107 shown on IFR enroute charts is MORCA. Its applicable for the quadrangle in which the text is enclosed. • MCA- Minimum Crossing Altitude- the altitude required to pass from one victor airway to another via a transition point (VOR) when Lost Comm • MRA- Minimum Reception Altitude- guarantees reception for NavAids and Comm at or above this altitude • MAA- Maximum allowable altitude- this is to help you from entering an altitude that 2 VORs operating on the same frequency could interfere and misguide you • MVA- Minimum Vectoring Altitude- this is known to ATC, they factor this in when providing radar vectors', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-15; FAA-H-8083-16; IFR Enroute Charts; Terminal Procedures Publications', 'V. Navigation Systems', 'IR.V.B Departure, En Route, and Arrival Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0019', 'Instrument', 'Instrument Airplane', 'IR.VI.A; IR.VI.B; IR.VI.D', 'How do you know what category your aircraft is in for IFR approaches?', '• Check the maneuvering tables in the 2nd page of the approach plate book. the category is based on the aircrafts speed (1.3Vso). With the known category you can check the table on the approach plate itself for the DH and visibility', '14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'VI. Instrument Approach Procedures', 'IR.VI.A Non-precision Approach; IR.VI.B Precision Approach; IR.VI.D Circling Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0020', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.VI.B', 'Name the components of an ILS system', '• Beacons • Localizer • Glideslope • Approach lighting of some kind (RAIL)', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'II. Preflight Procedures; VI. Instrument Approach Procedures', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.VI.B Precision Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0021', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.VI.B', 'What color are the marker beacon lights?', '• Blue finish', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'II. Preflight Procedures; VI. Instrument Approach Procedures', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.VI.B Precision Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0022', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.VI.B', 'What is the difference between a localizer signal and a regular VOR signal?', '• VOR is omnidirectional. LOC has one direction. 10 degrees on either side for VOR (5 degrees either side), only 5 degrees total for LOC (2.5 either side). LOC is 4 times more sensitive so it keeps the airplane in a more tighter space.', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'II. Preflight Procedures; VI. Instrument Approach Procedures', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.VI.B Precision Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0023', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.VI.B', 'What is compass locator outer/ middle marker?', '• LOM Compass locator outer marker blue dash tones. It has an NDB its collocated so you can fly to it (the NDB) (KRNT) middle 2 code hear. • or LMM locator middle marker (KRNT) last 2 code hear. Amber. • Inner marker is white.', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'II. Preflight Procedures; VI. Instrument Approach Procedures', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.VI.B Precision Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0024', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.VI.B', 'What can you substitute for an outer marker?', '• You can use NDB beacon or request a Precision Approach Radar (PAR) • NDB approach plate, if it says ‘or GPS’ then you can fly GPS', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'II. Preflight Procedures; VI. Instrument Approach Procedures', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.VI.B Precision Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0025', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.VI.B', 'What can you substitute for a middle marker?', '• Any legitimate nav aid. Cross radial from a VOR, GPS fix, …. Anything published to get an absolute fix.', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'II. Preflight Procedures; VI. Instrument Approach Procedures', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.VI.B Precision Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0026', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'When can you log instrument flight time?', '• A person may log instrument time only for that flight time when the person operates the aircraft solely (sole manipulator) by reference to instruments under actual or simulated instrument flight conditions 4 • Keep in mind when flying between cloud layers (not in cloud!) is not considered IFR – VFR time- Spence’s comment', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0027', 'Instrument', 'Instrument Airplane', 'IR.I.A', 'What are the conditions under which a pilot may conduct and log IAPs?', '• Actual instrument flight conditions in an aircraft • Simulated instrument flight conditions using a view limiting device flown in an aircraft with a safety pilot. i. Safety pilot is one with a minimum private pilot with the appropriate category and class ratings required to operate that aircraft, valid appropriate medical to act as flight crew member, and if flight required to be done on IFR flight plan, they must have valid and current instrument rating • Simulated instrument flight conditions conduced in any FAA approved flight simulator/ full flight simulator (FFS), flight training device (FTD), aviation training device (ATD) with a CFII • A combination of A) to C)', '14 CFR part 61; AC 68-1; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25', 'I. Preflight Preparation', 'IR.I.A Pilot Qualifications', 'knowledge', 'standard'),
    ('IR-ASEL-0028', 'Instrument', 'Instrument Airplane', 'IR.III.A', 'Explain VFR on top', '• You want out of clouds due to turbulence- relief for yourself and/or passengers due to discomfort or passenger motion sickness • It’s still an IFR clearance so stay on your routing. But you can change altitudes- advisory to notify ATC • VFR cruising magnetic rules for altitude rules kick in! odd+500/even+500 • Clouds and Visibility Requirements i. >10,000 ft. 5SM, 1 mile from clouds, 1000 ft. above or below ii. <10,000 ft. 3SM 2000 ft. from clouds, 1000 ft. above, 500 ft. below iii. Cannot exceed 18,000 ft. – CLASS A, IFR ONLY! iv. Cannot descend below MEA • Flying VFR on the top you have towering cumulus in front of you what should you do? i. Request from ATC a deviation on route around it.', '14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16', 'III. Air Traffic Control (ATC) Clearances and Procedures', 'IR.III.A Compliance with Air Traffic Control Clearances', 'knowledge', 'standard'),
    ('IR-ASEL-0029', 'Instrument', 'Instrument Airplane', 'IR.III.A', 'Explain Cruise Clearance', '• Assigned altitude to MEA is your space. If you descend below it and report it, you need permission to climb back up. • This clearance also ALWAYS clears you for the approach as well.', '14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16', 'III. Air Traffic Control (ATC) Clearances and Procedures', 'IR.III.A Compliance with Air Traffic Control Clearances', 'knowledge', 'standard'),
    ('IR-ASEL-0030', 'Instrument', 'Instrument Airplane', 'IR.VII.A', 'Explain lost communication altitude requirements', '• See #31', '14 CFR §91.185; AIM; FAA-H-8083-15; FAA-H-8083-16', 'VII. Emergency Operations', 'IR.VII.A Loss of Communications', 'knowledge', 'standard'),
    ('IR-ASEL-0031', 'Instrument', 'Instrument Airplane', 'IR.VII.A', 'What do you do when you go lost communication?', '• Check my radios + CBs? Headset jack? Co-pilot head set jack? Push to talk button? • Squawk 7600 • Follow logic i. If VFR, stay VFR and go land. After landing call ATC on ground and state your arrival (Tell them you are ok) ii. If IFR, follow rules for IMC 1. Routing a. Last assigned b. Last told to expect 5 c. As Filed (flight plan) 2. Altitude (whichever is highest) a. Last assigned b. Last told to expect c. MEA, but must also comply with MRA and MCA. Which ever is the highest, fly it. 3. Time a. If you haven’t got a clearance before lost COMM, go shoot approach with full procedure turns if there is no clearance limit b. If you were told to proceed to some point (i.e. PAE VOR) then you hold until ETA. You can hold on the radial you arrived on if not marked on the approach plate for that given point. If no ETA, just go shoot it. c. If you arrive late, just go shoot approach', '14 CFR §91.185; AIM; FAA-H-8083-15; FAA-H-8083-16', 'VII. Emergency Operations', 'IR.VII.A Loss of Communications', 'scenario', 'standard'),
    ('IR-ASEL-0032', 'Instrument', 'Instrument Airplane', 'IR.VI.D; IR.VI.E', 'What is the difference between a straight in approach and a straight in landing?', '• Straight in approach does not require PT • Straight in Landing i. if the centerline of runway and approach heading are within 30 degrees of each other, then you can do a straight in landing (lower DH minimum) ii. If you are greater than 30 degrees for the approach, then you must circle and land. Higher DH (circling minimum) iii. This could also mean you have a really fast step down- see name of approach (VOR OLM-A) look for the letter (A,B,C) indication', '14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications; 14 CFR §91.175; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'VI. Instrument Approach Procedures', 'IR.VI.D Circling Approach; IR.VI.E Landing from an Instrument Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0033', 'Instrument', 'Instrument Airplane', 'IR.VI.A; IR.VI.B', 'When is a procedure turn not required?', '• It is not required when you are cleared straight in approach • Transition route says NO PT • Holding pattern given instead of PT (holding in lieu of PT)', '14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'VI. Instrument Approach Procedures', 'IR.VI.A Non-precision Approach; IR.VI.B Precision Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0034', 'Instrument', 'Instrument Airplane', 'IR.VI.E', 'When can you descend below MDA or DH?', '• Decision Height (DH) is for precision approach GPS(LPV) or ILS – 200 ft AAE; usually lower than MDA • Minimum Decision Altitude (MDA) is for non-precision approach (i.e. VOR) 1. Visibility on approach procedure – 600 (1/2) 2. Normal maneuvers 3. Runway environment in-sight -Other lights on runway- runway lights, end of runway lights, wind sock, etc. Rabbit lighting you can see okay, then come down but 100’ + TDZE. Not lower until other requirements can be met. 4. VDP- Visual Descent Point (V) on the approach plate i. PAPI/VASI out of service then you can see VDP, stay above MDS/DH until you get passed the VDP', '14 CFR §91.175; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'VI. Instrument Approach Procedures', 'IR.VI.E Landing from an Instrument Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0035', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.V.A', 'How can you check the VOR Receiver accuracy?', '• VOT page 283 in chart supplements only 4 in WA i. Insert procedure 6 • Air and Ground FAA approved page 282 for WA i. Ground +/- 4° ii. Air +/- 6° • Dual Receiver Check i. Using 2 VORs you can dial in the same VOR frequency and check to see if the difference between both of them is within 4° • Single VOR check i. If you can’t do a, b, or c, then do d especially if say you are 100 miles away from nearest VOR or VOT. ii. Take off VFR and go to nearest victor airways iii. Using VFR sections, note the blue victor airway and find a landmark, get over the landmark and check your VOR based on the radial. Its airborne check so apply +/- 6° tolerance band', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; IFR Enroute Charts; POH/AFM', 'II. Preflight Procedures; V. Navigation Systems', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.V.A Intercepting and Tracking Navigational Systems and DME Arcs', 'knowledge', 'standard'),
    ('IR-ASEL-0036', 'Instrument', 'Instrument Airplane', 'IR.I.B', 'How far from a Severe TS must you keep away?', '• 20NM', '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28', 'I. Preflight Preparation', 'IR.I.B Weather Information', 'knowledge', 'standard'),
    ('IR-ASEL-0037', 'Instrument', 'Instrument Airplane', 'IR.I.B; IR.II.A', 'Tail plane Stall: Ice Building up on the tail, high angle of attack and stalls.', null, '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28; 14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'I. Preflight Preparation; II. Preflight Procedures', 'IR.I.B Weather Information; IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0038', 'Instrument', 'Instrument Airplane', 'IR.II.A', 'Aircraft performance: Advantages and Disadvantages of FWD and AFT CG', '• Aft CG less stable, better fuel economy • FWD CG more stable, less desirable fuel economy', '14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'II. Preflight Procedures', 'IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0039', 'Instrument', 'Instrument Airplane', 'IR.I.C', 'NOTAMs- types', '• L- local NOTAMs- “like to know” unlighted crane, don’t go down Taxiway B with wing span greater than 80ft • D-Distance NOTAMs- VFR is out of service along route. • FDC- regulatory in natures including changes to approach plate requirements such as DH change or a new transition. Must comply with', '14 CFR part 91; AIM; Chart Supplement; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-16; FAA-H-8083-25; IFR Enroute Charts; NOTAMs; IFR Navigation Charts', 'I. Preflight Preparation', 'IR.I.C Cross-Country Flight Planning', 'knowledge', 'standard'),
    ('IR-ASEL-0040', 'Instrument', 'Instrument Airplane', 'IR.I.B', 'Why is frost dangerous?', '• Causes early airflow separation and loss in lift.', '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28', 'I. Preflight Preparation', 'IR.I.B Weather Information', 'knowledge', 'standard'),
    ('IR-ASEL-0041', 'Instrument', 'Instrument Airplane', 'IR.I.B; IR.II.A', 'Scenario based – Icing. What would you do if you have RIME ice building.', '• keep you speed up • no flaps • see if you can descend to an altitude below FL – advise ATC of situation • Remember for this aircraft- flight is prohibited into known icing conditions check AFM.', '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28; 14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'I. Preflight Preparation; II. Preflight Procedures', 'IR.I.B Weather Information; IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'scenario', 'standard'),
    ('IR-ASEL-0042', 'Instrument', 'Instrument Airplane', 'IR.I.B', 'Stratiform vs Cumuliform clouds', '• Big puffy vertical vs more fog like cloud. • Cumuliform is unstable so its got more turbulence in it', '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28', 'I. Preflight Preparation', 'IR.I.B Weather Information', 'knowledge', 'standard'),
    ('IR-ASEL-0043', 'Instrument', 'Instrument Airplane', 'IR.II.B; IR.V.A', 'Service Volumes (off route fight)- page 27 Chart Supplements', '• Terminal (T) from 1000’ to 12,000’ service guaranteed for 25 NM from VOR • High (H) from 1000’ to 18,000’ service guaranteed for 40 NM from VOR • Low (L) from 1000’ to 14,500’ and 14,500’ to 18,000’ service guaranteed for 40 NM and 100 NM from VOR respectively • Chart supplements shows (T) when its only Terminal. H assumes also L & T. L assumes also T.', '14 CFR part 91; AC 90-100; AC 90-105; AC 90-107; AC 91-78; AC 91.21-1; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM; 14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; IFR Enroute Charts; POH/AFM', 'II. Preflight Procedures; V. Navigation Systems', 'IR.II.B Aircraft Flight Instruments and Navigation Equipment; IR.V.A Intercepting and Tracking Navigational Systems and DME Arcs', 'knowledge', 'standard'),
    ('IR-ASEL-0044', 'Instrument', 'Instrument Airplane', 'IR.VI.D; IR.VI.E', 'Circling Protected Area', '1.3 Miles Cat A; 1.5 Miles Cat B; Up to about 7000’, about that it extends but don’t worry about that.', '14 CFR part 91; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications; 14 CFR §91.175; AIM; FAA-H-8083-15; FAA-H-8083-16; Terminal Procedures Publications', 'VI. Instrument Approach Procedures', 'IR.VI.D Circling Approach; IR.VI.E Landing from an Instrument Approach', 'knowledge', 'standard'),
    ('IR-ASEL-0045', 'Instrument', 'Instrument Airplane', 'IR.I.B', 'AIRMETS vs SIGMETS', 'AIRMET: For Light A/C+ VFR identifying Light + Mod Icing and turbulence. SIGMET: For all aircrafts identifying significant weather conditions including sand storms, volcano eruptions, etc.', '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28', 'I. Preflight Preparation', 'IR.I.B Weather Information', 'knowledge', 'standard'),
    ('IR-ASEL-0046', 'Instrument', 'Instrument Airplane', 'IR.II.A', 'Can you permit passengers to use portable electronic devices?', 'Restrict it to anytime but critical phases of flight (take off and landing). High RF outputting devices cannot use at anytime.', '14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'II. Preflight Procedures', 'IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0047', 'Instrument', 'Instrument Airplane', 'IR.I.B', 'Be able to read METAR/TAF', null, '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28', 'I. Preflight Preparation', 'IR.I.B Weather Information', 'knowledge', 'standard'),
    ('IR-ASEL-0048', 'Instrument', 'Instrument Airplane', 'IR.I.B; IR.II.A', 'Standard lapse rate for icing- cruising 8000, OAT shows -4C, picking up ice. So go BELOW. 6000’', null, '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28; 14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'I. Preflight Preparation; II. Preflight Procedures', 'IR.I.B Weather Information; IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0049', 'Instrument', 'Instrument Airplane', 'IR.I.B; IR.II.A', 'Types of icing to worry about:', 'Pitot ice, induction icing (carb aircraft), rime ice, clear ice, mixed ice, restrictions', '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28; 14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'I. Preflight Preparation; II. Preflight Procedures', 'IR.I.B Weather Information; IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0050', 'Instrument', 'Instrument Airplane', 'IR.I.B; IR.II.A', 'My aircraft is prohibited to fly in known icing.', null, '14 CFR part 91; AC 91-92; AIM; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-25; FAA-H-8083-28; 14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'I. Preflight Preparation; II. Preflight Procedures', 'IR.I.B Weather Information; IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0051', 'Instrument', 'Instrument Airplane', 'IR.II.A', 'Know your airspeeds', 'Vr Rotation Speed 65 mph (55 kts); Vx Best Angle of Climb 74 mph (64 kts); Vy Best Rate of Climb 85 mph (74 kts); VFE Flaps extension speed 115 mph (100 kts) or look for white arc; VA maneuvering speed 129 mph @ max gross weight; Vno maximum structural cruising speed 137 mph (119 kt); Vne never exceed speed 168 mph (146 kts); VG Best Glide Speed 83 mph (72 kts); Vs0 55 mph (47 kts); Vs1 64 mph (55 kts)', '14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'II. Preflight Procedures', 'IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard'),
    ('IR-ASEL-0052', 'Instrument', 'Instrument Airplane', 'IR.II.A', 'Max Crosswind', '17 kts', '14 CFR part 91; AC 91-74; FAA-H-8083-2; FAA-H-8083-3; FAA-H-8083-15; FAA-H-8083-25; POH/AFM', 'II. Preflight Procedures', 'IR.II.A Aircraft Systems Related to Instrument Flight Rules (IFR) Operations', 'knowledge', 'standard');
-- ============================================================
-- VERIFY MASTER SOURCE
-- ============================================================

do $$
declare
  v_count integer;
  v_unknown text;
begin
  select count(*)
  into v_count
  from _poa_master_import;

  if v_count <> 251 then
    raise exception
      'ACS applicability repair stopped: expected 251 source rows, found %.',
      v_count;
  end if;

  select string_agg(token, ', ' order by token)
  into v_unknown
  from (
    select distinct trim(value) as token
    from _poa_master_import s
    cross join lateral regexp_split_to_table(
      s.certificate_applicability,
      '\s*,\s*'
    ) as value
    where trim(value) not in (
      'Private',
      'Commercial',
      'Flight Instructor',
      'Instrument'
    )
  ) unknowns;

  if v_unknown is not null then
    raise exception
      'ACS applicability repair stopped: unknown certificate applicability token(s): %',
      v_unknown;
  end if;
end
$$;
-- ============================================================
-- BUILD AUTHORITATIVE CERTIFICATE-LEVEL APPLICABILITY
-- ============================================================

create temporary table _expected_poa_acs_applicability
on commit drop
as
with source_certificates as (
  select
    s.source_question_id,
    s.question,
    s.acs_reference as original_acs_reference,

    trim(certificate_token) as certificate_token,

    case trim(certificate_token)
      when 'Private'
        then 'Private Pilot'
      when 'Commercial'
        then 'Commercial Pilot'
      when 'Flight Instructor'
        then 'Flight Instructor'
      when 'Instrument'
        then 'Instrument Rating'
    end as certificate_name,

    case trim(certificate_token)
      when 'Private'
        then 'PA.'
      when 'Commercial'
        then 'CA.'
      when 'Flight Instructor'
        then 'FI.'
      when 'Instrument'
        then 'IR.'
    end as reference_prefix

  from _poa_master_import s

  cross join lateral regexp_split_to_table(
    s.certificate_applicability,
    '\s*,\s*'
  ) as certificate_token
),

certificate_references as (
  select
    sc.source_question_id,
    sc.question,
    sc.original_acs_reference,
    sc.certificate_name,

    string_agg(
      trim(reference_part),
      '; '
      order by reference_ordinal
    ) as certificate_acs_reference

  from source_certificates sc

  cross join lateral regexp_split_to_table(
    sc.original_acs_reference,
    '\s*;\s*'
  ) with ordinality
    as refs(reference_part, reference_ordinal)

  where
    trim(reference_part) like sc.reference_prefix || '%'

  group by
    sc.source_question_id,
    sc.question,
    sc.original_acs_reference,
    sc.certificate_name
)

select *
from certificate_references;
-- Every declared certificate applicability must resolve to a
-- matching certificate-specific ACS reference.

do $$
declare
  v_expected integer;
  v_resolved integer;
begin
  select count(*)
  into v_expected
  from (
    select
      s.source_question_id,
      trim(certificate_token)
    from _poa_master_import s
    cross join lateral regexp_split_to_table(
      s.certificate_applicability,
      '\s*,\s*'
    ) as certificate_token
  ) x;

  select count(*)
  into v_resolved
  from _expected_poa_acs_applicability;

  if v_expected <> v_resolved then
    raise exception
      'ACS applicability repair stopped: expected % certificate mappings but only % resolved to certificate-specific ACS references.',
      v_expected,
      v_resolved;
  end if;
end
$$;
-- ============================================================
-- VERIFY ALL 251 SOURCE QUESTIONS MATCH EXISTING LIBRARY ROWS
-- ============================================================

do $$
declare
  v_match_count integer;
begin
  select count(distinct s.source_question_id)
  into v_match_count
  from _poa_master_import s

  join public.poa_questions q
    on lower(trim(q.question)) =
       lower(trim(s.question))

   and q.source_document_name =
       'ACS Oral Exam Question Bank - Instrument Rating Added.xlsx'

   and q.is_active = true;

  if v_match_count <> 251 then
    raise exception
      'ACS applicability repair stopped: expected to match 251 imported questions, matched %.',
      v_match_count;
  end if;
end
$$;
-- ============================================================
-- REMOVE ONLY THE STALE APPLICABILITY ROWS FOR THIS WORKBOOK
-- ============================================================

delete from public.poa_question_acs_applicability a

using public.poa_questions q

where
  q.id = a.question_id

  and q.source_document_name =
      'ACS Oral Exam Question Bank - Instrument Rating Added.xlsx';
-- ============================================================
-- INSERT AUTHORITATIVE APPLICABILITY
-- ============================================================

insert into public.poa_question_acs_applicability (
  question_id,
  certificate_name,
  acs_reference
)

select distinct
  q.id,
  e.certificate_name,
  e.certificate_acs_reference

from _expected_poa_acs_applicability e

join public.poa_questions q
  on lower(trim(q.question)) =
     lower(trim(e.question))

 and q.source_document_name =
     'ACS Oral Exam Question Bank - Instrument Rating Added.xlsx'

 and q.is_active = true

on conflict (
  question_id,
  certificate_name
)

do update
set
  acs_reference = excluded.acs_reference;
-- ============================================================
-- FINAL VERIFICATION / NOTICES
-- ============================================================

do $$
declare
  r record;
  v_expected integer;
  v_actual integer;
begin
  for r in

    select
      certificate_name,
      count(distinct source_question_id) as expected_questions

    from _expected_poa_acs_applicability

    group by certificate_name

    order by certificate_name

  loop

    v_expected := r.expected_questions;

    select count(distinct a.question_id)
    into v_actual

    from public.poa_question_acs_applicability a

    join public.poa_questions q
      on q.id = a.question_id

    where
      q.source_document_name =
        'ACS Oral Exam Question Bank - Instrument Rating Added.xlsx'

      and q.is_active = true

      and a.certificate_name =
        r.certificate_name;

    if v_actual <> v_expected then
      raise exception
        'ACS applicability repair verification failed for %: expected %, found %.',
        r.certificate_name,
        v_expected,
        v_actual;
    end if;

    raise notice
      'POA ACS applicability: % = % questions',
      r.certificate_name,
      v_actual;

  end loop;
end
$$;
commit;
